-- Terminal – usklađivanje anonimnih TC-ova sa ekranom terminala (TRM-A01, TRM-A05) i novi TC-ovi TRM-A11 – TRM-A18.
-- wrangler d1 execute qa-hub-mediastream-db --remote --file=./terminal-anon-update.sql

UPDATE player_test_cases SET title = 'Početni ekran bez prijave', steps = '["Pogledaj početni ekran terminala (bez prijave).", "Provjeri zaglavlje, tabove, listu sportova, lijevi meni, listu događaja, betslip i donju traku."]', expected = 'Zaglavlje: tabovi SPORT BETS / LIVE BETS / RESULTS, vrijeme i datum, zastava jezika i dugme LOGIN.
Podtabovi: TOP EVENTS, LAST MINUTE, TODAY''S, ALL EVENTS, OUTRIGHTS; red sportova (Soccer, Tennis, Basketball, Volleyball, Handball, Ice Hockey, Boxing, MMA) sa strelicama.
Lijevo: ALL EVENTS, Top Tournaments i lige/države sa brojem događaja, straničenje (npr. 1/12).
Sredina: događaji sa kvotama (1X2, Over/Under), Stats i More (+N), straničenje (npr. 1/6).
Desno: BETSLIP (0) sa SINGLE/COMBI i SYSTEM, "Your Bet Slip is empty at the moment", Total Odds, Clear All i Book.
Dolje: Back, Home, Ticket search, postavke, info, Games & Results; ID terminala i verzija (npr. ID: 299, v18.0.1).
Kvote odgovaraju webu za iste događaje.
Napomena: tab TOP EVENTS je zasivljen – provjeriti da li je namjerno (nema top događaja) ili je bug.', images = '[{"src": "/player-guide/trm-01-anonimni.jpg", "caption": "Terminal – početni ekran za anonimnog korisnika (Sport Bets → All Events)"}]', updated_at = datetime('now') WHERE suite = 'terminal' AND tc_code = 'TRM-A01';
UPDATE player_test_cases SET title = 'Ticket search – provjera tiketa', steps = '["U donjoj traci klikni \"Ticket search\".", "Skeniraj barkod tiketa ili unesi ID.", "Ponovi za dobitni, gubitni i otvoreni tiket i za nepostojeći ID."]', expected = 'Ticket search prikazuje status tiketa (otvoren / dobitan / gubitan), selekcije, kvote i iznose – isto kao Verify Ticket na webu.
Nepostojeći ID daje jasnu poruku.', updated_at = datetime('now') WHERE suite = 'terminal' AND tc_code = 'TRM-A05';
INSERT INTO player_test_cases (suite, module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) SELECT 'terminal', 'Anonimni korisnik', 'TRM-A11', 'Navigacija na terminalu', 'Pozitivni', 'Medium', 'Testni terminal u shopu (staging) je uključen i spojen.
Korisnik NIJE prijavljen na terminalu.', '["Klikni redom SPORT BETS, LIVE BETS, RESULTS.", "U SPORT BETS klikni TOP EVENTS, LAST MINUTE, TODAY''S, ALL EVENTS, OUTRIGHTS.", "Prođi kroz sportove strelicama lijevo/desno.", "Koristi strelice gore/dolje za straničenje lijevog menija (1/12) i liste događaja (1/6).", "Klikni Back i Home sa različitih ekrana."]', '', 'Svaki tab i sport otvara odgovarajuću ponudu; aktivni tab/sport je jasno označen.
Straničenje pokazuje tačan broj stranica i ne preskače/ponavlja stavke; na prvoj/zadnjoj stranici odgovarajuća strelica je neaktivna.
Back vraća na prethodni ekran, Home na početni.
Navigacija ne prazni betslip.', '', '[{"src": "/player-guide/trm-01-anonimni.jpg", "caption": "Terminal – početni ekran za anonimnog korisnika (Sport Bets → All Events)"}]', 10, 'Claude' WHERE NOT EXISTS (SELECT 1 FROM player_test_cases WHERE suite = 'terminal' AND tc_code = 'TRM-A11');
