INSERT INTO player_test_cases (suite, module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) SELECT 'terminal', 'Anonimni korisnik', 'TRM-A13', 'Betslip: Single/Combi, System, Clear All, Book', 'Pozitivni', 'High', 'Testni terminal u shopu (staging) je uključen i spojen.
Korisnik NIJE prijavljen na terminalu.', '["Dodaj 1 selekciju, pa još 2 iz različitih događaja.", "Prebaci između SINGLE / COMBI i SYSTEM.", "Provjeri Total Odds.", "Klikni Clear All.", "Dodaj selekcije i klikni Book."]', '', 'Brojač BETSLIP (N) i Total Odds su tačni (proizvod kvota za combi).
